package view

import (
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract"

	"github.com/charmbracelet/lipgloss"
)

// RenderModelPicker renders the model picker overlay as a string.
// It shows a 2-column provider grid; once a provider is selected it also
// shows a model list column to the right. The current model is marked with
// "*". Keyboard hints render at the bottom.
//
// Layout:
//   - Title: "Select Model"
//   - Provider grid: 2 entries per row, selected provider highlighted with "❯"
//   - Model column: appears when provider selected, scrolling list with "*" for current
//   - Footer: keyboard hints (↑/↓ navigate, Enter confirm, Esc cancel)
//
// Styles contains the semantic Lip Gloss styles needed by the model picker renderer.
type Styles struct {
	ActivePill lipgloss.Style
	Label      lipgloss.Style
	Selected   lipgloss.Style
	Normal     lipgloss.Style
	Good       lipgloss.Style
	Dim        lipgloss.Style
}

// Render renders the model picker overlay as a string.
func Render(state contract.State, styles Styles) string {
	if state.Width < 30 {
		return renderNarrow(state, styles)
	}
	return renderWide(state, styles)
}

func renderWide(state contract.State, styles Styles) string {
	var b strings.Builder

	// Title
	title := "  Select Model  "
	b.WriteString(styles.ActivePill.Width(state.Width).Render(title))
	b.WriteString("\n\n")

	// Provider section header (only show when providers exist)
	if len(state.Providers) > 0 {
		b.WriteString(styles.Label.Render("  Provider") + "\n")
	}

	// Provider grid: 2 per row
	providerCols := 2
	providerColWidth := (state.Width - 4) / providerCols
	if providerColWidth < 20 {
		providerColWidth = 20
	}

	selectedStyle := styles.Selected
	normalStyle := styles.Normal

	for row := 0; row < len(state.Providers); row += providerCols {
		line := "  "
		for col := 0; col < providerCols && row+col < len(state.Providers); col++ {
			idx := row + col
			line += providerRow(state.Providers[idx], idx == state.SelectedProviderIndex, providerColWidth, selectedStyle, normalStyle)
		}
		b.WriteString(line + "\n")
	}

	// Model column when provider is selected
	if selectedProv, ok := contract.SelectedProvider(state); ok {
		b.WriteString("\n")
		b.WriteString(styles.Label.Render("  Model ("+selectedProv.Label+")") + "\n")

		// Calculate model list height
		modelStartY := 4 + (len(state.Providers)+1)/2    // title + header + provider rows
		modelMaxHeight := state.Height - modelStartY - 3 // -3 for hints

		visibleModels := state.Models
		if modelMaxHeight > 0 && len(visibleModels) > modelMaxHeight {
			// Scroll window: center on selected if possible
			half := modelMaxHeight / 2
			start := state.SelectedModelIndex - half
			if start < 0 {
				start = 0
			}
			end := start + modelMaxHeight
			if end > len(visibleModels) {
				end = len(visibleModels)
				start = end - modelMaxHeight
				if start < 0 {
					start = 0
				}
			}
			visibleModels = visibleModels[start:end]
		}

		for _, entry := range visibleModels {
			b.WriteString(renderModelRow(modelRow{
				entry:    entry,
				provider: selectedProv,
				state:    state,
				maxWidth: state.Width - 6,
				truncate: true,
				styles:   styles,
			}) + "\n")
		}
	}

	// Keyboard hints at bottom
	b.WriteString("\n")
	b.WriteString(styles.Dim.Render("  ↑/↓ navigate  ·  Enter confirm  ·  Esc cancel"))

	return b.String()
}

func renderNarrow(state contract.State, styles Styles) string {
	var b strings.Builder

	title := "  Select Model  "
	b.WriteString(styles.ActivePill.Width(state.Width).Render(title))
	b.WriteString("\n\n")

	selectedStyle := styles.Selected
	normalStyle := styles.Normal

	// Single column providers
	for i, entry := range state.Providers {
		prefix, style := selectionAffordance(i == state.SelectedProviderIndex, selectedStyle, normalStyle)
		b.WriteString(prefix + style.Render(entry.Label) + "\n")
	}

	// Model list when provider selected
	if selectedProv, ok := contract.SelectedProvider(state); ok {
		b.WriteString("\n")
		b.WriteString(styles.Label.Render("  Models for "+selectedProv.Label+":") + "\n")

		for _, entry := range state.Models {
			b.WriteString(renderModelRow(modelRow{
				entry:    entry,
				provider: selectedProv,
				state:    state,
				styles:   styles,
			}) + "\n")
		}
	}

	b.WriteString("\n")
	b.WriteString(styles.Dim.Render("  ↑/↓ navigate  ·  Enter confirm  ·  Esc cancel"))

	return b.String()
}

package view

import (
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract"
	"github.com/charmbracelet/lipgloss"
)

type modelRow struct {
	entry    contract.ModelEntry
	provider contract.ProviderEntry
	state    contract.State
	maxWidth int
	truncate bool
	styles   Styles
}

func renderModelRow(row modelRow) string {
	prefix, style := selectionAffordance(false, row.styles.Selected, row.styles.Normal)
	marker := "  "

	if selectedModel, ok := contract.SelectedModel(row.state); ok && selectedModel.ID == row.entry.ID {
		prefix, style = selectionAffordance(true, row.styles.Selected, row.styles.Normal)
	}

	if contract.IsCurrentModel(row.state, row.provider.ID, row.entry.ID) {
		marker = "* "
		style = row.styles.Good
	}

	label := row.entry.Label
	if row.truncate {
		label = truncateLabel(label, row.maxWidth, 4)
	}
	return prefix + marker + style.Render(label)
}

func providerRow(entry contract.ProviderEntry, selected bool, width int, selectedStyle, normalStyle lipgloss.Style) string {
	prefix, style := selectionAffordance(selected, selectedStyle, normalStyle)
	label := truncateLabel(entry.Label, width, 3)
	padded := label + strings.Repeat(" ", width-len(label)-3)
	return prefix + style.Render(padded)
}

func selectionAffordance(selected bool, selectedStyle, normalStyle lipgloss.Style) (string, lipgloss.Style) {
	if selected {
		return "❯ ", selectedStyle
	}
	return "  ", normalStyle
}

func truncateLabel(label string, width int, markerSpace int) string {
	if len(label) > width-markerSpace {
		return label[:width-markerSpace-3] + "…"
	}
	return label
}

package normalization

import (
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract/schema"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract/textinput"
)

// ProviderEntry trims a provider entry and fills an empty label from the
// provider ID. The bool is false when the provider has no stable ID.
func ProviderEntry(entry schema.ProviderEntry) (schema.ProviderEntry, bool) {
	id, label, ok := normalizeIDLabel(entry.ID, entry.Label)
	if !ok {
		return schema.ProviderEntry{}, false
	}
	return schema.ProviderEntry{ID: id, Label: label}, true
}

// ModelEntry trims a model entry and fills an empty label from the model ID.
// The bool is false when the model has no stable ID.
func ModelEntry(entry schema.ModelEntry) (schema.ModelEntry, bool) {
	id, label, ok := normalizeIDLabel(entry.ID, entry.Label)
	if !ok {
		return schema.ModelEntry{}, false
	}
	return schema.ModelEntry{ID: id, Label: label}, true
}

// ModelEntries trims model entries, drops entries without stable IDs, and
// fills empty labels from model IDs.
func ModelEntries(entries []schema.ModelEntry) []schema.ModelEntry {
	out := make([]schema.ModelEntry, 0, len(entries))
	for _, entry := range entries {
		model, ok := ModelEntry(entry)
		if !ok {
			continue
		}
		out = append(out, model)
	}
	return out
}

// Catalog trims catalog entries, drops providers without stable IDs, drops
// models without stable IDs, and drops providers left without models.
func Catalog(catalog []schema.CatalogProvider) []schema.CatalogProvider {
	out := make([]schema.CatalogProvider, 0, len(catalog))
	for _, entry := range catalog {
		provider, ok := ProviderEntry(entry.Provider)
		if !ok {
			continue
		}
		models := ModelEntries(entry.Models)
		if len(models) == 0 {
			continue
		}
		out = append(out, schema.CatalogProvider{
			Provider: provider,
			Models:   models,
		})
	}
	return out
}

func normalizeIDLabel(rawID, rawLabel string) (string, string, bool) {
	id := textinput.TrimBoundary(rawID)
	if id == "" {
		return "", "", false
	}
	return id, textinput.FirstNonEmpty(textinput.TrimBoundary(rawLabel), id), true
}

package textinput

import "strings"

// TrimBoundary trims whitespace at model-picker contract boundaries while
// preserving caller-owned casing and internal spacing.
func TrimBoundary(value string) string {
	return strings.TrimSpace(value)
}

// FirstNonEmpty returns the first non-empty already-normalized value.
func FirstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

package slash

import (
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract/textinput"
)

// Argument returns the free-form model argument after the slash command.
func Argument(input string) string {
	trimmed := textinput.TrimBoundary(input)
	if trimmed == "" {
		return ""
	}
	fields := strings.Fields(trimmed)
	if len(fields) <= 1 {
		return ""
	}
	idx := strings.Index(trimmed, fields[1])
	if idx < 0 {
		return strings.Join(fields[1:], " ")
	}
	return textinput.TrimBoundary(trimmed[idx:])
}

package selection

import (
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract/identity"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract/schema"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract/textinput"
)

// ModelListFocused reports whether keyboard navigation is currently inside
// the model list instead of the provider list.
func ModelListFocused(state schema.State) bool {
	return state.SelectedModelIndex >= 0
}

// MoveIndex moves a selected index within a list without wrapping.
func MoveIndex(index, delta, count int) int {
	if count <= 0 {
		return -1
	}
	if index < 0 {
		index = 0
	}
	index += delta
	if index < 0 {
		return 0
	}
	if index >= count {
		return count - 1
	}
	return index
}

// Provider returns the provider currently focused by the user.
func Provider(state schema.State) (schema.ProviderEntry, bool) {
	return selectedValue(state.Providers, state.SelectedProviderIndex)
}

// Model returns the model currently focused by the user.
func Model(state schema.State) (schema.ModelEntry, bool) {
	return selectedValue(state.Models, state.SelectedModelIndex)
}

// IsCurrentModel reports whether a provider/model row represents the current
// runtime selection shown by the picker.
func IsCurrentModel(state schema.State, providerID, modelID string) bool {
	return state.CurrentModel == modelID && identity.ProviderIDEqual(state.CurrentProvider, providerID)
}

// ConfirmedResult returns the provider/model pair emitted when the operator
// confirms the current focus. If no model row is focused, the active model is
// kept as the fallback for the selected provider.
func ConfirmedResult(state schema.State) (schema.Result, bool) {
	selectedProv, ok := Provider(state)
	if !ok {
		return schema.Result{}, false
	}
	selectedModel := state.CurrentModel
	if focusedModel, ok := Model(state); ok {
		selectedModel = focusedModel.ID
	}
	return schema.Result{Provider: selectedProv.ID, Model: selectedModel}, true
}

// NormalizeConfirmed returns a catalog-valid provider/model pair from a
// confirmed selection. Unknown models fall back to the first model for a known
// provider; unknown providers and explicitly empty models are preserved after
// trimming so callers can decide how to report or apply them.
func NormalizeConfirmed(catalog []schema.CatalogProvider, provider, model string) (string, string) {
	provider = textinput.TrimBoundary(provider)
	model = textinput.TrimBoundary(model)
	for _, entry := range catalog {
		if !identity.ProviderIDEqual(entry.Provider.ID, provider) {
			continue
		}
		if model != "" {
			for _, candidate := range entry.Models {
				if candidate.ID == model {
					return provider, model
				}
			}
		}
		if len(entry.Models) > 0 {
			return provider, entry.Models[0].ID
		}
	}
	return provider, model
}

func selectedValue[T any](values []T, index int) (T, bool) {
	if index < 0 || index >= len(values) {
		var zero T
		return zero, false
	}
	return values[index], true
}

package navigation

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract"
)

// Update handles keyboard events for the model picker state. The returned bool
// is true when result should be emitted to the caller.
func Update(msg tea.Msg, state contract.State) (contract.State, contract.Result, bool) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		return updateKey(msg, state)
	}
	return state, contract.Result{}, false
}

func updateKey(msg tea.KeyMsg, state contract.State) (contract.State, contract.Result, bool) {
	switch msg.Type {
	case tea.KeyUp:
		if contract.ModelListFocused(state) {
			state.SelectedModelIndex = contract.MoveSelection(state.SelectedModelIndex, -1, len(state.Models))
		} else {
			state.SelectedProviderIndex = contract.MoveSelection(state.SelectedProviderIndex, -1, len(state.Providers))
		}
		return state, contract.Result{}, false

	case tea.KeyDown:
		if contract.ModelListFocused(state) {
			state.SelectedModelIndex = contract.MoveSelection(state.SelectedModelIndex, 1, len(state.Models))
		} else {
			state.SelectedProviderIndex = contract.MoveSelection(state.SelectedProviderIndex, 1, len(state.Providers))
		}
		return state, contract.Result{}, false

	case tea.KeyLeft:
		if contract.ModelListFocused(state) {
			state.SelectedModelIndex = -1
		}
		return state, contract.Result{}, false

	case tea.KeyRight:
		if state.SelectedProviderIndex >= 0 && !contract.ModelListFocused(state) && len(state.Models) > 0 {
			state.SelectedModelIndex = 0
		}
		return state, contract.Result{}, false

	case tea.KeyEnter:
		if result, ok := contract.ConfirmedResult(state); ok {
			return state, result, true
		}
		return state, contract.Result{}, false

	case tea.KeyEscape:
		return state, contract.Result{}, true
	}
	return state, contract.Result{}, false
}

