package view

import (
	"strings"
	"testing"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/modelpicker/contract"
)

func TestRenderWideShowsSharedChromeAndCurrentModel(t *testing.T) {
	state := contract.State{
		Width:                 60,
		Height:                20,
		Providers:             []contract.ProviderEntry{{ID: "openai", Label: "OpenAI"}},
		Models:                []contract.ModelEntry{{ID: "gpt-4.1", Label: "GPT 4.1"}},
		SelectedProviderIndex: 0,
		SelectedModelIndex:    0,
		CurrentProvider:       "openai",
		CurrentModel:          "gpt-4.1",
	}

	out := Render(state, Styles{})
	for _, want := range []string{"Select Model", "Provider", "Model (OpenAI)", "* GPT 4.1", "Enter confirm"} {
		if !strings.Contains(out, want) {
			t.Fatalf("Render wide missing %q in:\n%s", want, out)
		}
	}
}

func TestRenderNarrowUsesSameChromeAndModelSection(t *testing.T) {
	state := contract.State{
		Width:                 20,
		Height:                20,
		Providers:             []contract.ProviderEntry{{ID: "anthropic", Label: "Anthropic"}},
		Models:                []contract.ModelEntry{{ID: "claude", Label: "Claude"}},
		SelectedProviderIndex: 0,
		SelectedModelIndex:    -1,
	}

	out := Render(state, Styles{})
	for _, want := range []string{"Select Model", "❯ Anthropic", "Models for Anthropic:", "Claude", "Enter confirm"} {
		if !strings.Contains(out, want) {
			t.Fatalf("Render narrow missing %q in:\n%s", want, out)
		}
	}
}

